/* Shared data + renderer. Cover is embedded so it always loads.
   For per-book covers, add a "img" field to a book (e.g. img:"covers/it-works.jpg"). */
const COVER="data:image/webp;base64,";
const books=[
 {t:"Gratitude Journal",p:"White Falcon Publishing",u:"https://store.whitefalconpublishing.com/collections/latest-books/products/gratitude-journal"},
 {t:"My Diary of Dreams",p:"White Falcon Publishing",u:"https://store.whitefalconpublishing.com/products/my-diary-of-dreams"},
 {t:"It Works",p:"Literature Chronicle",u:"https://literaturechronicle.com/product/it-works/"},
 {t:"Daily Planner",p:"Literature Chronicle",u:"https://literaturechronicle.com/product/daily-planner/"},
 {t:"Travel Gratitude Journal",p:"Literature Chronicle",u:"https://literaturechronicle.com/product/travel-gratitude-journal/"},
 {t:"My Top 10 Goals Journal",p:"Literature Chronicle",u:"https://literaturechronicle.com/product/my-top-10-goals-journal/"},
 {t:"Letters to God: Hello God, It's Me",p:"Literature Chronicle",u:"https://literaturechronicle.com/product/letters-to-god-hello-god-its-me/"},
 {t:"5 Year Memory Journal",p:"Literature Chronicle",u:"https://literaturechronicle.com/product/5-year-memory-journal/"},
 {t:"Magnificent Outcome",p:"Literature Chronicle",u:"https://literaturechronicle.com/product/magnificent-outcome/"}
];
function renderBooks(id,list){
  const g=document.getElementById(id);
  list.forEach(b=>{
    const alt=b.t.replace(/"/g,'&quot;');
    const a=document.createElement('article');a.className='card';
    a.innerHTML='<a class="cover" href="'+b.u+'" target="_blank" rel="noopener" aria-label="'+alt+'"><img src="'+(b.img||COVER)+'" alt="'+alt+' cover"></a>'
      +'<h2>'+b.t+'</h2><small>'+b.p+'</small>'
      +'<a class="btn" href="'+b.u+'" target="_blank" rel="noopener">Buy Now →</a>';
    g.appendChild(a);
  });
}
document.querySelectorAll('.yr').forEach(e=>e.textContent=new Date().getFullYear());
